from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object, mode: str = "mean") -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    if mode == "mean":
        sums = defaultdict(int)
    else:
        maxs = {}
    counts = defaultdict(int)
    degraded = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        parsed = _parse_observation(obs)
        if parsed is None:
            return {"ok": False, "error": "bad observation"}
        x, y, value, quality = parsed

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        if x < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue

        if y < 0:
            dropped += 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        if mode == "mean":
            sums[key] += value
        elif key not in maxs or value > maxs[key]:
            maxs[key] = value
        counts[key] += 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    if mode == "mean":
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    else:
        cells = _max_rows(maxs, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _parse_observation(obs: object) -> tuple[int, int, int, int] | None:
    if not isinstance(obs, dict):
        return None
    x = obs.get("x")
    y = obs.get("y")
    value = obs.get("value")
    quality = obs.get("quality")
    if (
        not isinstance(x, int)
        or not isinstance(y, int)
        or not isinstance(value, int)
        or not isinstance(quality, int)
        or quality < 0
        or quality > 100
    ):
        return None
    return (x, y, value, quality)


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _max_rows(maxs: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(maxs[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    if mode == "max":
        values = defaultdict(int)
    else:
        sums = defaultdict(int)
    counts = defaultdict(int)
    degraded = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if not _has_int(obs, "x") or not _has_int(obs, "y"):
            return {"ok": False, "error": "bad observation"}
        if not _has_int(obs, "value") or not _has_int(obs, "quality"):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        # Grid cell for the x coordinate. Points landing just past the last
        # column still wire to the edge cell within half a cell of slack;
        # anything further is out of bounds and dropped.
        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        # Same boundary logic for the y coordinate / row index.
        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

        key = (row, col)
        if counts[key] >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        if mode == "max":
            values[key] = max(values[key], obs["value"])
        else:
            sums[key] += obs["value"]
        counts[key] += 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    if mode == "max":
        cells = _value_rows(values, counts, width, height, raw["fill_value"])
    else:
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _value_rows(values: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(values[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _has_int(obs: dict, field: str) -> bool:
    return field in obs and isinstance(obs[field], int)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
