def accumulate_grid(raw: object) -> dict:
    validated = _validate(raw)
    if validated is None:
        return {"ok": False, "error": "malformed input"}
    error = validated.get("error")
    if error:
        return {"ok": False, "error": error}

    grid = validated["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = validated["fill_value"]
    observations = validated["observations"]
    mode = validated["mode"]

    sums = {}
    maxes = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        if obs["value"] > maxes.get(key, fill_value):
            maxes[key] = obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _cell_rows(sums, maxes, counts, width, height, fill_value, mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate(raw: object) -> dict | None:
    if not isinstance(raw, dict):
        return None
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"error": "bad observations"}
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"error": "bad mode"}
    return {
        "grid": grid,
        "fill_value": raw["fill_value"],
        "observations": observations,
        "mode": mode,
    }


def _cell_rows(sums: dict, maxes: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                cells.append(fill_value)
            elif mode == "max":
                cells.append(maxes[key])
            else:
                cells.append(sums[key] // counts[key])
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

from typing import Optional

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object, mode: str = "mean") -> dict:
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    tolerance = cell_size // 2
    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    maxes: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = rejected = saturated = 0
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        quality = _obs_field(obs, "quality")
        if quality is None:
            return {"ok": False, "error": "bad observation"}
        if quality < 0 or quality > 100:
            return {"ok": False, "error": "bad observation"}

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        value = _obs_field(obs, "value")
        if value is None:
            return {"ok": False, "error": "bad observation"}
        x = _obs_field(obs, "x")
        if x is None:
            return {"ok": False, "error": "bad observation"}
        y = _obs_field(obs, "y")
        if y is None:
            return {"ok": False, "error": "bad observation"}

        col = _map_index(x, cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _map_index(y, cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        maxes[key] = max(maxes.get(key, value), value)
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _cell_rows(sums, maxes, counts, width, height, raw["fill_value"], mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _cell_value(key: tuple[int, int], sums: dict, maxes: dict, counts: dict, mode: str, fill_value: int) -> int:
    count = counts.get(key)
    if count is None:
        return fill_value
    if mode == "max":
        return maxes[key]
    return sums[key] // count


def _cell_rows(sums: dict, maxes: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    return [
        [_cell_value((row, col), sums, maxes, counts, mode, fill_value) for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    return [
        [
            "empty" if (row, col) not in counts
            else "degraded" if (row, col) in degraded
            else "good"
            for col in range(width)
        ]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _obs_field(obs: dict, field: str) -> Optional[int]:
    value = obs.get(field)
    if value is None or not isinstance(value, int):
        return None
    return value


def _map_index(coord: int, cell_size: int, dim: int, tolerance: int) -> Optional[int]:
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < tolerance:
            return dim - 1
        return None
    return index


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

import dataclasses

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


@dataclasses.dataclass(frozen=True)
class GridSpec:
    width: int
    height: int
    cell_size: int
    fill_value: int
    observations: list

def accumulate_grid(raw: object, mode: str = "mean") -> dict:
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}
    spec_or_error = _parse_spec(raw)
    if not spec_or_error[0]:
        return {"ok": False, "error": spec_or_error[1]}
    spec = spec_or_error[1]

    sums: dict = {}
    maxes: dict = {}
    counts: dict = {}
    degraded: set = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = spec.cell_size // 2

    for obs in spec.observations:
        key = _classify(obs, spec, tolerance)
        if key is None:
            if obs["quality"] < MIN_QUALITY:
                rejected += 1
            else:
                dropped += 1
            continue

        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if key not in maxes or obs["value"] > maxes[key]:
            maxes[key] = obs["value"]
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    all_cells = spec.width * spec.height
    if mode == "max":
        cells = _max_rows(maxes, counts, spec)
    else:
        cells = _averaged_rows(sums, counts, spec)
    flags = _flag_rows(counts, degraded, spec)
    coverage = len(counts) * 100 // all_cells
    line = _summary_line(all_cells, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }



def _classify(obs: dict, spec: GridSpec, tolerance: int):
    if obs["quality"] < MIN_QUALITY:
        return None

    col = _project(obs["x"], spec.width, spec.cell_size, tolerance)
    if col is None:
        return None
    row = _project(obs["y"], spec.height, spec.cell_size, tolerance)
    if row is None:
        return None

    return (row, col)


def _project(coord: int, extent: int, cell_size: int, tolerance: int) -> int | None:
    """Map a coordinate to a cell index, or None if it lies outside the grid."""
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= extent:
        if coord - extent * cell_size < tolerance:
            index = extent - 1
        else:
            return None
    return index


def _parse_spec(raw: object) -> tuple:
    """Return (ok, spec_or_error)."""
    if not isinstance(raw, dict):
        return False, "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return False, "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return False, "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return False, "bad grid"

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return False, "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return False, "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return False, "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return False, "bad fill value"

    observations = raw["observations"]
    if not isinstance(observations, list):
        return False, "bad observations"

    for obs in observations:
        if not isinstance(obs, dict):
            return False, "bad observation"
        if "x" not in obs or not isinstance(obs["x"], int):
            return False, "bad observation"
        if "y" not in obs or not isinstance(obs["y"], int):
            return False, "bad observation"
        if "value" not in obs or not isinstance(obs["value"], int):
            return False, "bad observation"
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return False, "bad observation"
        if obs["quality"] < 0 or obs["quality"] > 100:
            return False, "bad observation"

    return True, GridSpec(width, height, cell_size, raw["fill_value"], observations)


def _averaged_rows(sums: dict, counts: dict, spec: GridSpec) -> list:
    rows = []
    for row in range(spec.height):
        cells = []
        for col in range(spec.width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(spec.fill_value)
        rows.append(cells)
    return rows


def _max_rows(maxes: dict, counts: dict, spec: GridSpec) -> list:
    rows = []
    for row in range(spec.height):
        cells = []
        for col in range(spec.width):
            key = (row, col)
            if key in counts:
                cells.append(maxes[key])
            else:
                cells.append(spec.fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, spec: GridSpec) -> list:
    rows = []
    for row in range(spec.height):
        flags = []
        for col in range(spec.width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

