from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    # --- structural validation -------------------------------------------
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    for field in ("grid", "observations", "fill_value"):
        if field not in raw:
            return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    for field in ("width", "height", "cell_size"):
        if field not in grid:
            return {"ok": False, "error": "bad grid"}

    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}

    fill_value = raw["fill_value"]
    if not isinstance(fill_value, int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    mode = raw.get("mode", "mean")
    if not isinstance(mode, str) or mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    # --- accumulation ------------------------------------------------------
    sums: dict[tuple[int, int], int] = {}
    maxs: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if (
            not isinstance(obs, dict)
            or not all(isinstance(obs.get(f), int) for f in ("x", "y", "value", "quality"))
        ):
            return {"ok": False, "error": "bad observation"}
        quality = obs["quality"]
        if quality < 0 or quality > 100:
            return {"ok": False, "error": "bad observation"}
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        x, y, value = obs["x"], obs["y"], obs["value"]

        # map to (row, col), dropping points outside the grid
        if x < 0 or y < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        maxs[key] = value if key not in counts else max(maxs[key], value)
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _value_rows(sums, maxs, counts, mode, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _value_rows(sums: dict, maxs: dict, counts: dict, mode: str, width: int, height: int, fill_value: int) -> list:
    return [
        [
            _cell_value(sums, maxs, counts, mode, r, c, fill_value)
            for c in range(width)
        ]
        for r in range(height)
    ]


def _cell_value(sums: dict, maxs: dict, counts: dict, mode: str, r: int, c: int, fill_value: int) -> int:
    if (r, c) not in counts:
        return fill_value
    if mode == "max":
        return maxs[(r, c)]
    return sums[(r, c)] // counts[(r, c)]


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(r, c)] // counts[(r, c)] if (r, c) in counts else fill_value for c in range(width)]
        for r in range(height)
    ]


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    return [
        [
            "empty" if (r, c) not in counts else ("degraded" if (r, c) in degraded else "good")
            for c in range(width)
        ]
        for r in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

