def _validate_input(member: dict, payment: dict) -> dict | None:
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}
    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}
    if member["status"] not in ("active", "lapsed", "suspended"):
        return {"ok": False, "error": "unknown status"}
    return None


def _check_tier(member: dict) -> dict | None:
    if member["tier"] not in _VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    return None


def _check_amount_method(payment: dict) -> dict | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in _VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    return None


def _pay(member: dict, payment: dict, action: str, fee: int) -> dict:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    receipt = f"{payment['method']}:{member['id']}:{action}:{fee}"
    return {"ok": True, "status": action, "fee": fee, "receipt": receipt}


def _renew_active(member: dict, payment: dict) -> dict:
    err = _check_tier(member) or _check_amount_method(payment)
    if err:
        return err
    fee = TIER_FEES[member["tier"]]
    return _pay(member, payment, "renewed", fee)


def _renew_lapsed(member: dict, payment: dict) -> dict:
    err = _check_tier(member)
    if err:
        return err
    if not isinstance(member.get("expired_days"), int) or member["expired_days"] < 0:
        return {"ok": False, "error": "bad expiry"}
    err = _check_amount_method(payment)
    if err:
        return err
    if member["expired_days"] <= GRACE_DAYS:
        action, fee = "renewed", TIER_FEES[member["tier"]] + LATE_FEE
    else:
        action, fee = "reinstated", TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
    return _pay(member, payment, action, fee)


def _renew_suspended(member: dict, payment: dict) -> dict:
    err = _check_tier(member)
    if err:
        return err
    if not isinstance(member.get("strikes"), int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    err = _check_amount_method(payment)
    if err:
        return err
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    return _pay(member, payment, "reactivated", fee)


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    err = _validate_input(raw_member, raw_payment)
    if err:
        return err
    if raw_member["status"] == "active":
        return _renew_active(raw_member, raw_payment)
    if raw_member["status"] == "lapsed":
        return _renew_lapsed(raw_member, raw_payment)
    return _renew_suspended(raw_member, raw_payment)

