from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Fold observations into an average grid, returning cell values and flags.

    Public contract: takes a raw dict and returns either an error dict
    ({"ok": False, "error": <message>}) or a success dict; the exact
    messages, keys, and arithmetic are part of the interface.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict) or "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        cell, outcome = _place(obs, width, height, cell_size, tolerance)
        if outcome == "error":
            return cell  # cell is the error dict
        if outcome == "rejected":
            rejected += 1
            continue
        if outcome == "dropped":
            dropped += 1
            continue
        # outcome == "ok": cell is a (row, col) key
        if counts.get(cell, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        if mode == "mean":
            sums[cell] = sums.get(cell, 0) + obs["value"]
        else:
            sums[cell] = max(sums.get(cell, 0), obs["value"])
        counts[cell] = counts.get(cell, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[cell] = True

    cells = _cell_rows(sums, counts, width, height, raw["fill_value"], mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _place(obs: object, width: int, height: int, cell_size: int, tolerance: int):
    """Validate an observation and map it to a cell.

    Returns (key_or_dict, outcome) where outcome is one of
    "error" | "rejected" | "dropped" | "ok". On "error" the first
    element is an error result dict; on "ok" it is a (row, col) tuple.
    """
    if not isinstance(obs, dict):
        return {"ok": False, "error": "bad observation"}, "error"
    if "x" not in obs or not isinstance(obs["x"], int):
        return {"ok": False, "error": "bad observation"}, "error"
    if "y" not in obs or not isinstance(obs["y"], int):
        return {"ok": False, "error": "bad observation"}, "error"
    if "value" not in obs or not isinstance(obs["value"], int):
        return {"ok": False, "error": "bad observation"}, "error"
    if "quality" not in obs or not isinstance(obs["quality"], int):
        return {"ok": False, "error": "bad observation"}, "error"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return {"ok": False, "error": "bad observation"}, "error"

    if obs["quality"] < MIN_QUALITY:
        return None, "rejected"

    col = _project(obs["x"], width * cell_size, cell_size, width, tolerance)
    if col is None:
        return None, "dropped"
    row = _project(obs["y"], height * cell_size, cell_size, height, tolerance)
    if row is None:
        return None, "dropped"
    return (row, col), "ok"


def _project(coord: int, extent: int, cell_size: int, dims: int, tolerance: int):
    """Map a coordinate to a column/row index, or None if out of range."""
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dims:
        # A coordinate can still land in the last cell when it overshoots
        # the nominal extent by less than one cell-size tolerance.
        if coord - extent < tolerance:
            return dims - 1
        return None
    return index


def _cell_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    precincts = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                cells.append(fill_value)
            elif mode == "max":
                cells.append(sums[key])
            else:
                cells.append(sums[key] // counts[key])
        precincts.append(cells)
    return precincts


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            flags.append("empty" if key not in counts else ("degraded" if key in degraded else "good"))
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells, filled, dropped, rejected, saturated, coverage) -> str:
    return "cells={};filled={};dropped={};rejected={};saturated={};coverage={}".format(
        total_cells, filled, dropped, rejected, saturated, coverage
    )

