from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90, "student": 20}
_SUPPORTED_METHODS = ("card", "transfer")


def _validate_member(member: dict) -> str | None:
    """Return an error message for a malformed member, else None."""
    if "id" not in member or "status" not in member or "tier" not in member:
        return "missing member field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    return None


def _validate_payment(payment: dict) -> str | None:
    """Return an error message for a bad payment, else None.

    Mirrors the original ordering: field presence, then non-negative int amount,
    then supported method. Errors other than the value checks here are handled
    up front (missing payment field) and per status (insufficient funds).
    """
    if "amount" not in payment or "method" not in payment:
        return "missing payment field"
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in _SUPPORTED_METHODS:
        return "unsupported method"
    return None


def _base_fee(tier: str) -> int | None:
    """Return the base tier fee for a known tier, else None."""
    return TIER_FEES.get(tier)


def _success(status: str, fee: int, payment: dict, member_id: str) -> dict:
    receipt = f"{payment['method']}:{member_id}:{status}:{fee}"
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}

    member = raw_member
    payment = raw_payment

    member_error = _validate_member(member)
    if member_error:
        return {"ok": False, "error": member_error}

    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    base_fee = _base_fee(member["tier"])
    if base_fee is None:
        return {"ok": False, "error": "unknown tier"}

    if status == "active":
        payment_error = _validate_payment(payment)
        if payment_error:
            return {"ok": False, "error": payment_error}
        if payment["amount"] < base_fee:
            return {"ok": False, "error": "insufficient payment"}
        return _success("renewed", base_fee, payment, member["id"])

    if status == "lapsed":
        expired = member.get("expired_days")
        if not isinstance(expired, int) or expired < 0:
            return {"ok": False, "error": "bad expiry"}
        payment_error = _validate_payment(payment)
        if payment_error:
            return {"ok": False, "error": payment_error}
        if expired <= GRACE_DAYS:
            fee = base_fee + LATE_FEE
            new_status = "renewed"
        else:
            fee = base_fee + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return _success(new_status, fee, payment, member["id"])

    if status == "suspended":
        strikes = member.get("strikes")
        if not isinstance(strikes, int) or strikes < 0:
            return {"ok": False, "error": "bad strikes"}
        if strikes >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
        payment_error = _validate_payment(payment)
        if payment_error:
            return {"ok": False, "error": payment_error}
        fee = base_fee + base_fee // 2
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return _success("reactivated", fee, payment, member["id"])

    return {"ok": False, "error": "unknown status"}

