        deviations.append(abs(values[index] - _window_median(values, index)))
    return deviations


def _window_median(values: list, index: int) -> int:
    previous = values[index - 1] if index > 0 else values[index]
    following = values[index + 1] if index + 1 < len(values) else values[index]
    return _median3(previous, values[index], following)


def _median3(a: int, b: int, c: int) -> int:
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    return b


def _classify(deviation: int, hard_limit: int) -> str:
    if deviation >= hard_limit:
        return "invalid"
    if deviation >= SEVERE_SPIKE:
        return "severe"
    if deviation >= MODERATE_SPIKE:
        return "moderate"
    if deviation >= MINOR_SPIKE:
        return "minor"
    return "clean"


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    labels = []
    total = 0
    worst = 0
    for deviation in deviations:
        label = _classify(deviation, hard_limit)
        score = SCORES[label]
        labels.append(label)
        total = total + score
        if score > worst:
            worst = score
    return labels, total, worst


def _worst_label(worst_score: int) -> str:
    for label in reversed(LABELS):
        if worst_score >= SCORES[label]:
            return label
    return "clean"


def _label_counts(labels: list) -> dict:
    counts = {label: 0 for label in LABELS}
    for label in labels:
        counts[label] = counts[label] + 1
    return counts


def _trend(values: list) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current = current + 1
            if current > longest:
                longest = current
    return longest


def _outlier_indices(labels: list) -> list:
    return [
        index
        for index, label in enumerate(labels)
        if label == "severe" or label == "invalid"
    ]


def _verdict(total: int) -> str:
    if total >= 100:
        return "fail"
    if total >= 25:
        return "warn"
    return "pass"


def _summary_line(count: int, gaps: int, worst_score: int, total: int) -> str:
    return f"n={count};gaps={gaps};worst={_worst_label(worst_score)};score={total}"

