from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_ERRORS = {
    "input": "malformed input",
    "missing": "missing field",
    "grid": "bad grid",
    "width": "bad width",
    "height": "bad height",
    "cell": "bad cell size",
    "fill": "bad fill value",
    "mode": "bad mode",
    "observations": "bad observations",
    "observation": "bad observation",
}


def _fail(kind: str) -> dict:
    return {"ok": False, "error": _ERRORS[kind]}


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return False
    return 0 <= obs["quality"] <= 100


def _bin(coord: int, extent: int, cell_size: int, tolerance: int):
    """Map an absolute coord to a cell index, snapping into the last cell
    when it lands within `tolerance` of the far edge, else None."""
    index = coord // cell_size
    if index < extent:
        return index
    if index == extent and coord - extent * cell_size < tolerance:
        return extent - 1
    return None


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return _fail("input")
    if not all(field in raw for field in ("grid", "observations", "fill_value")):
        return _fail("missing")

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return _fail("grid")
    if not all(field in grid for field in ("width", "height", "cell_size")):
        return _fail("grid")

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not (isinstance(width, int) and 1 <= width <= MAX_DIM):
        return _fail("width")
    if not (isinstance(height, int) and 1 <= height <= MAX_DIM):
        return _fail("height")
    if not (isinstance(cell_size, int) and cell_size >= 1):
        return _fail("cell")
    if not isinstance(raw["fill_value"], int):
        return _fail("fill")

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return _fail("mode")

    observations = raw["observations"]
    if not isinstance(observations, list):
        return _fail("observations")

    sums: dict[tuple[int, int], int] = {}
    maxs: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _valid_observation(obs):
            return _fail("observation")

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col = _bin(obs["x"], width, cell_size, tolerance)
        row = _bin(obs["y"], height, cell_size, tolerance)
        if col is None or row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        sums[key] = sums.get(key, 0) + obs["value"]
        maxs[key] = max(maxs.get(key, obs["value"]), obs["value"])
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    cells = _cell_rows(sums, maxs, counts, width, height, raw["fill_value"], mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    total = width * height
    line = _summary_line(total, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _cell_rows(sums: dict, maxs: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                cells.append(fill_value)
            elif mode == "max":
                cells.append(maxs[key])
            else:
                cells.append(sums[key] // counts[key])
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

