        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

