export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: "standard" | "suite" | "villa" | "cabin";
  minNights: number;
  maxNights: number;
  minStay?: number;
  maxGuests: number;
  baseRate: number;
  highSurge: number;
  guestSurcharge?: { over: number; amount: number };
  flatFee?: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    name: "standard",
    minNights: 1,
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    highSurge: 30,
  },
  suite: {
    name: "suite",
    minNights: 1,
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highSurge: 60,
    guestSurcharge: { over: 2, amount: 25 },
  },
  villa: {
    name: "villa",
    minNights: 1,
    maxNights: 28,
    minStay: 3,
    maxGuests: 8,
    baseRate: 300,
    highSurge: 120,
    flatFee: 500,
  },
  cabin: {
    name: "cabin",
    minNights: 1,
    maxNights: 10,
    maxGuests: 6,
    baseRate: 50,
    highSurge: 15,
  },
};

function isInt(v: unknown): v is number {
  return Number.isInteger(v);
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isInt(req.loyaltyYears) || req.loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyalty = req.loyaltyYears as number;

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights;
  if (!isInt(nights) || nights < config.minNights || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minStay !== undefined && nights < config.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = req.guests;
  if (!isInt(guests) || guests < 1 || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const high = req.season === "high";

  let total = config.baseRate * nights;
  if (high) {
    total += config.highSurge * nights;
  }

  const privileged = loyalty >= 3 || req.coupon === "VIP";
  if (privileged) {
    total -= Math.floor(total / 10);
  }

  if (config.guestSurcharge !== undefined && guests > config.guestSurcharge.over) {
    total += config.guestSurcharge.amount;
  }
  if (config.flatFee !== undefined) {
    total += config.flatFee;
  }

  const policy = privileged ? "flex" : "strict";
  const line = `${config.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

