# Severity bands for spike labels and their weighted scores. Ordered from most
# to least severe; a deviation is classified by the first band its magnitude
# clears. The hard limit binds from above (any deviation reaching it is
# "invalid"), so it overrides every named band.
_SEVERITY = (
    ("severe", 25, 12),
    ("moderate", 10, 6),
    ("minor", 3, 3),
    ("clean", 0, 0),
)

