export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Season = "low" | "high";

interface BookingConfig {
  maxNights: number;
  minStay?: number;
  maxGuests: number;
  lowRate: number;
  highDelta: number;
  guestSurcharge?: { over: number; amount: number };
  flatFee?: number;
}

const CONFIG: Record<string, BookingConfig> = {
  standard: { maxNights: 14, maxGuests: 2, lowRate: 80, highDelta: 30 },
  suite: {
    maxNights: 21,
    maxGuests: 4,
    lowRate: 150,
    highDelta: 60,
    guestSurcharge: { over: 2, amount: 25 },
  },
  villa: {
    maxNights: 28,
    minStay: 3,
    maxGuests: 8,
    lowRate: 300,
    highDelta: 120,
    flatFee: 500,
  },
  cabin: { maxNights: 10, maxGuests: 6, lowRate: 50, highDelta: 15 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CONFIG[req.category as string];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (cfg.minStay !== undefined && nights < cfg.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  const season: Season = req.season as Season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const vip = req.coupon === "VIP" || (req.loyaltyYears as number) >= 3;
  let total = cfg.lowRate * nights + (season === "high" ? cfg.highDelta : 0) * nights;
  if (vip) {
    total -= Math.floor(total / 10);
  }
  if (cfg.guestSurcharge !== undefined && guests > cfg.guestSurcharge.over) {
    total += cfg.guestSurcharge.amount;
  }
  if (cfg.flatFee !== undefined) {
    total += cfg.flatFee;
  }

  const policy = vip ? "flex" : "strict";
  const line = `${String(req.category)}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

