export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa" | "cabin";
type Season = "low" | "high";

interface Request {
  category: Category;
  season: Season;
  nights: number;
  guests: number;
  loyaltyYears: number;
  coupon: unknown;
}

const RATES = {
  standard: { perNight: 80, highSurcharge: 30, nightsMax: 14, guestsMax: 2 },
  suite: { perNight: 150, highSurcharge: 60, nightsMax: 21, guestsMax: 4 },
  villa: { perNight: 300, highSurcharge: 120, nightsMax: 28, guestsMax: 8 },
  cabin: { perNight: 50, highSurcharge: 15, nightsMax: 10, guestsMax: 6 },
} as const;

const CATEGORIES: Category[] = ["standard", "suite", "villa", "cabin"];
const SEASONS: Season[] = ["low", "high"];

function isCategory(v: unknown): v is Category {
  return CATEGORIES.includes(v as Category);
}

function isSeason(v: unknown): v is Season {
  return SEASONS.includes(v as Season);
}

function isInt(v: unknown): v is number {
  return typeof v === "number" && Number.isInteger(v);
}

function isIntIn(v: unknown, min: number, max: number): boolean {
  return isInt(v) && v >= min && v <= max;
}

interface Rule {
  msg: string;
  check: (r: Record<string, unknown>, category: Category, rate: Rate) => boolean;
}

interface Rate {
  perNight: number;
  highSurcharge: number;
  nightsMax: number;
  guestsMax: number;
}

function villaRules(): Rule[] {
  return [
    {
      msg: "villa minimum stay",
      check: (r, category) => category !== "villa" || (r.nights as number) >= 3,
    },
  ];
}

function rulesFor(rate: Rate, category: Category): Rule[] {
  return [
    {
      msg: "bad nights",
      check: (r) => isIntIn(r.nights, 1, rate.nightsMax),
    },
    ...(category === "villa" ? villaRules() : []),
    {
      msg: "bad guests",
      check: (r) => isIntIn(r.guests, 1, rate.guestsMax),
    },
    {
      msg: "bad season",
      check: (r) => isSeason(r.season),
    },
  ];
}

type ParseResult = { req: Request } | { error: string };

function validate(r: Record<string, unknown>, category: Category): string | null {
  const rate = RATES[category];
  for (const rule of rulesFor(rate, category)) {
    if (!rule.check(r, category, rate)) {
      return rule.msg;
    }
  }
  return null;
}

function parseRequest(raw: unknown): ParseResult {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed request" };
  }
  const r = raw as Record<string, unknown>;
  if (!isInt(r.loyaltyYears) || r.loyaltyYears < 0) {
    return { error: "bad loyalty" };
  }
  if (!isCategory(r.category)) {
    return { error: "unknown category" };
  }
  const category = r.category;

  const error = validate(r, category);
  if (error !== null) {
    return { error };
  }

  return {
    req: {
      category,
      season: r.season as Season,
      nights: r.nights as number,
      guests: r.guests as number,
      loyaltyYears: r.loyaltyYears as number,
      coupon: r.coupon,
    },
  };
}

function flatFee(req: Request): number {
  if (req.category === "suite" && req.guests > 2) {
    return 25;
  }
  return req.category === "villa" ? 500 : 0;
}

function price(req: Request): { total: number; policy: string; line: string } {
  const rate = RATES[req.category];
  const premium = req.loyaltyYears >= 3 || req.coupon === "VIP";

  const base = req.nights * (rate.perNight + (req.season === "high" ? rate.highSurcharge : 0));
  const discounted = premium ? base - Math.floor(base / 10) : base;
  const total = discounted + flatFee(req);

  const policy = premium ? "flex" : "strict";
  const line = `${req.category}:${req.nights}n:${total}:${policy}`;
  return { total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }
  return { ok: true, ...price(parsed.req) };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  label: string;
  baseRate: number;
  highRate: number;
  maxNights: number;
  minStay: number;
  maxGuests: number;
  guestSurcharge: number;
  flatFee: number;
}

const CATEGORIES = new Map<string, CategoryConfig>([
  [
    "standard",
    { label: "standard", baseRate: 80, highRate: 30, maxNights: 14, minStay: 1, maxGuests: 2, guestSurcharge: 0, flatFee: 0 },
  ],
  [
    "suite",
    { label: "suite", baseRate: 150, highRate: 60, maxNights: 21, minStay: 1, maxGuests: 4, guestSurcharge: 25, flatFee: 0 },
  ],
  [
    "villa",
    { label: "villa", baseRate: 300, highRate: 120, maxNights: 28, minStay: 3, maxGuests: 8, guestSurcharge: 0, flatFee: 500 },
  ],
  [
    "cabin",
    { label: "cabin", baseRate: 50, highRate: 15, maxNights: 10, minStay: 1, maxGuests: 6, guestSurcharge: 0, flatFee: 0 },
  ],
]);

function checkNights(req: Record<string, unknown>, cfg: CategoryConfig): string | null {
  const nights = (req.nights as number) ?? 0;
  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) {
    return "bad nights";
  }
  return nights < cfg.minStay ? "villa minimum stay" : null;
}

function checkGuests(req: Record<string, unknown>, cfg: CategoryConfig): string | null {
  const guests = (req.guests as number) ?? 0;
  if (!Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests) {
    return "bad guests";
  }
  return null;
}

function checkSeason(season: unknown): string | null {
  return season === "low" || season === "high" ? null : "bad season";
}

function firstFieldError(req: Record<string, unknown>, cfg: CategoryConfig): string | null {
  return (
    checkNights(req, cfg) ??
    checkGuests(req, cfg) ??
    checkSeason(req.season)
  );
}

function isPreferred(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= 3 || coupon === "VIP";
}

function computeTotal(
  cfg: CategoryConfig,
  nights: number,
  season: string,
  guests: number,
  preferred: boolean
): number {
  let total = cfg.baseRate * nights;
  if (season === "high") {
    total += cfg.highRate * nights;
  }
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  if (guests > 2 && cfg.guestSurcharge > 0) {
    total += cfg.guestSurcharge;
  }
  return total + cfg.flatFee;
}

function quoteCategory(
  req: Record<string, unknown>,
  loyaltyYears: number,
  cfg: CategoryConfig
): QuoteResult {
  const error = firstFieldError(req, cfg);
  if (error) {
    return { ok: false, error };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const preferred = isPreferred(loyaltyYears, req.coupon);
  const total = computeTotal(cfg, nights, req.season as string, guests, preferred);
  const policy = preferred ? "flex" : "strict";
  const line = `${cfg.label}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES.get(req.category as string);
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }
  return quoteCategory(req, req.loyaltyYears as number, cfg);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryRule {
  baseRate: number;
  highSeasonPerNight: number;
  maxNights: number;
  maxGuests: number;
  flatFee?: number;
  extraGuestSurcharge?: number;
  minStay?: number;
}

const RULES: Record<string, CategoryRule> = {
  standard: { baseRate: 80, highSeasonPerNight: 30, maxNights: 14, maxGuests: 2 },
  suite: {
    baseRate: 150,
    highSeasonPerNight: 60,
    maxNights: 21,
    maxGuests: 4,
    extraGuestSurcharge: 25,
  },
  villa: {
    baseRate: 300,
    highSeasonPerNight: 120,
    maxNights: 28,
    maxGuests: 8,
    minStay: 3,
    flatFee: 500,
  },
  cabin: { baseRate: 50, highSeasonPerNight: 15, maxNights: 10, maxGuests: 6 },
};

const ELIGIBLE_YEARS = 3;

function asInt(value: unknown): number | undefined {
  return typeof value === "number" && Number.isInteger(value) ? value : undefined;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = asInt(req.loyaltyYears);
  if (loyaltyYears === undefined || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const vip = req.coupon === "VIP";
  const flexible = vip || loyaltyYears >= ELIGIBLE_YEARS;

  const rule = RULES[String(req.category)];
  if (!rule) {
    return { ok: false, error: "unknown category" };
  }

  const nights = asInt(req.nights);
  if (nights === undefined || nights < 1 || nights > rule.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (rule.minStay !== undefined && nights < rule.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = asInt(req.guests);
  if (guests === undefined || guests < 1 || guests > rule.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const highSeason = req.season === "high";
  let total = rule.baseRate * nights;
  if (highSeason) {
    total += rule.highSeasonPerNight * nights;
  }
  if (flexible) {
    total -= Math.floor(total / 10);
  }
  if (rule.extraGuestSurcharge !== undefined && guests > 2) {
    total += rule.extraGuestSurcharge;
  }
  if (rule.flatFee !== undefined) {
    total += rule.flatFee;
  }

  const policy = flexible ? "flex" : "strict";
  const line = `${req.category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  maxNights: number;
  maxGuests: number;
  base: number;
  highExtra: number;
  addExtras: (total: number, guests: number) => number;
}

const CONFIG: Record<string, CategoryConfig> = {
  standard: { maxNights: 14, maxGuests: 2, base: 80, highExtra: 30, addExtras: (t) => t },
  suite:    { maxNights: 21, maxGuests: 4, base: 150, highExtra: 60, addExtras: (t, g) => (g > 2 ? t + 25 : t) },
  villa:    { maxNights: 28, maxGuests: 8, base: 300, highExtra: 120, addExtras: (t) => t + 500 },
  cabin:    { maxNights: 10, maxGuests: 6, base: 50, highExtra: 15, addExtras: (t) => t },
};

interface QuoteInput {
  category: "standard" | "suite" | "villa" | "cabin";
  nights: number;
  guests: number;
  highSeason: boolean;
  privileged: boolean;
}

interface Validated {
  ok: true;
  input: QuoteInput;
}

interface Rejected {
  ok: false;
  error: string;
}

type Validation = Validated | Rejected;

export function quoteBooking(raw: unknown): QuoteResult {
  const validation = validate(raw);
  if (!validation.ok) {
    return { ok: false, error: validation.error };
  }
  return computeQuote(validation.input);
}

function validate(raw: unknown): Validation {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyaltyYears = req.loyaltyYears as number;

  const category = req.category;
  if (category !== "standard" && category !== "suite" && category !== "villa" && category !== "cabin") {
    return { ok: false, error: "unknown category" };
  }

  const config = CONFIG[category];
  if (!Number.isInteger(req.nights) || (req.nights as number) < 1 || (req.nights as number) > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;

  if (category === "villa" && nights < 3) {
    return { ok: false, error: "villa minimum stay" };
  }

  if (!Number.isInteger(req.guests) || (req.guests as number) < 1 || (req.guests as number) > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return {
    ok: true,
    input: {
      category,
      nights,
      guests: req.guests as number,
      highSeason: req.season === "high",
      privileged: req.coupon === "VIP" || loyaltyYears >= 3,
    },
  };
}

function computeQuote(input: QuoteInput): QuoteResult {
  const config = CONFIG[input.category];

  let total = config.base * input.nights;
  if (input.highSeason) {
    total += config.highExtra * input.nights;
  }
  if (input.privileged) {
    total -= Math.floor(total / 10);
  }
  total = config.addExtras(total, input.guests);

  const policy = input.privileged ? "flex" : "strict";
  const line = `${input.category}:${input.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

