    discount: (loyalty, coupon) => coupon === "VIP" || loyalty >= 3,
    flex: (loyalty, coupon) => coupon === "VIP" || loyalty >= 3,
  },
  cabin: {
    minNights: 1,
    maxNights: 10,
    minGuests: 1,
    maxGuests: 6,
    base: 50,
    high: 15,
    extra: () => 0,
    discount: (loyalty, coupon) => loyalty >= 3 || coupon === "VIP",
    flex: (loyalty, coupon) => coupon === "VIP" || loyalty >= 3,
  },
  villa: {
    minNights: 1,
    maxNights: 28,
    minStay: 3,
    minGuests: 1,
    maxGuests: 8,
    base: 300,
    high: 120,
    extra: () => 500,
    discount: (loyalty, coupon) => coupon === "VIP" || loyalty > 2,
    flex: (loyalty, coupon) => coupon === "VIP" || loyalty >= 3,
  },
};

function between(value: unknown, min: number, max: number): value is number {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function malformedToError(category: string, nights: unknown, guests: unknown, season: unknown): string | undefined {
  const spec = CATEGORIES[category];
  if (!between(nights, spec.minNights, spec.maxNights)) {
    return "bad nights";
  }
  const n = nights as number;
  if (spec.minStay !== undefined && n < spec.minStay) {
    return "villa minimum stay";
  }
  if (!between(guests, spec.minGuests, spec.maxGuests)) {
    return "bad guests";
  }
  if (season !== "low" && season !== "high") {
    return "bad season";
  }
  return undefined;
}

function quoteFor(
  category: string,
  spec: CategorySpec,
  { nights, guests, season }: Validated,
  loyalty: number,
  coupon: unknown
): QuoteResult {
  let total = nights * spec.base;
  if (season === "high") {
    total = total + nights * spec.high;
  }
  if (spec.discount(loyalty, coupon)) {
    total = total - Math.floor(total / 10);
  }
  total = total + spec.extra(guests);

  const policy = spec.flex(loyalty, coupon) ? "flex" : "strict";
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyalty = req.loyaltyYears as number;

  const category = String(req.category);
  const spec = CATEGORIES[category];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const error = malformedToError(category, req.nights, req.guests, req.season);
  if (error) {
    return { ok: false, error };
  }

  const request: Validated = {
    nights: req.nights as number,
    guests: req.guests as number,
    season: req.season as string,
  };
  return quoteFor(category, spec, request, loyalty, req.coupon);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa" | "cabin";

interface CategoryRules {
  nightsMax: number;
  guestsMax: number;
  minStay?: number;
  base: number;
  highSurcharge: number;
  guestSurcharge?: number;
  flatFee?: number;
}

const RULES: Record<Category, CategoryRules> = {
  standard: { nightsMax: 14, guestsMax: 2, base: 80, highSurcharge: 30 },
  suite: { nightsMax: 21, guestsMax: 4, base: 150, highSurcharge: 60, guestSurcharge: 25 },
  villa: { nightsMax: 28, guestsMax: 8, minStay: 3, base: 300, highSurcharge: 120, flatFee: 500 },
  cabin: { nightsMax: 10, guestsMax: 6, base: 50, highSurcharge: 15 },
};

const SEASONS = new Set(["low", "high"]);
const INT_GE1 = (v: unknown) => Number.isInteger(v) && (v as number) >= 1;

const parseNights = (req: Record<string, unknown>, r: CategoryRules): number | string => {
  const n = req.nights as number;
  if (!INT_GE1(n) || n > r.nightsMax) return "bad nights";
  if (r.minStay !== undefined && n < r.minStay) return "villa minimum stay";
  return n;
};

const parseGuests = (req: Record<string, unknown>, r: CategoryRules): number | string => {
  const g = req.guests as number;
  if (!INT_GE1(g) || g > r.guestsMax) return "bad guests";
  return g;
};

const parseSeason = (req: Record<string, unknown>): string | null => {
  const s = req.season;
  if (typeof s !== "string" || !SEASONS.has(s)) return null;
  return s;
};

function quoteCategory(req: Record<string, unknown>, category: Category, loyalty: number): QuoteResult {
  const r = RULES[category];
  const nights = parseNights(req, r);
  if (typeof nights === "string") return { ok: false, error: nights };
  const guests = parseGuests(req, r);
  if (typeof guests === "string") return { ok: false, error: guests };
  const season = parseSeason(req);
  if (season === null) return { ok: false, error: "bad season" };

  const vip = req.coupon === "VIP";
  const rate = r.base + (season === "high" ? r.highSurcharge : 0);
  let total = rate * nights;
  if (loyalty >= 3 || vip) total -= Math.floor(total / 10);
  if (r.guestSurcharge !== undefined && guests > 2) total += r.guestSurcharge;
  if (r.flatFee !== undefined) total += r.flatFee;

  const policy = loyalty >= 3 || vip ? "flex" : "strict";
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyalty = req.loyaltyYears as number;

  switch (req.category) {
    case "standard":
      return quoteCategory(req, "standard", loyalty);
    case "suite":
      return quoteCategory(req, "suite", loyalty);
    case "villa":
      return quoteCategory(req, "villa", loyalty);
    case "cabin":
      return quoteCategory(req, "cabin", loyalty);
    default:
      return { ok: false, error: "unknown category" };
  }
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  label: string;
  maxNights: number;
  minNights: number;
  maxGuests: number;
  minStay: number;
  baseRate: number;
  highPremium: number;
  minStayExtra: number;
  extraGuestFee: number;
  freeGuestLimit: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    label: "standard",
    maxNights: 14,
    minNights: 1,
    maxGuests: 2,
    minStay: 1,
    baseRate: 80,
    highPremium: 30,
    minStayExtra: 0,
    extraGuestFee: 0,
    freeGuestLimit: 2,
  },
  suite: {
    label: "suite",
    maxNights: 21,
    minNights: 1,
    maxGuests: 4,
    minStay: 1,
    baseRate: 150,
    highPremium: 60,
    minStayExtra: 0,
    extraGuestFee: 25,
    freeGuestLimit: 2,
  },
  cabin: {
    label: "cabin",
    maxNights: 10,
    minNights: 1,
    maxGuests: 6,
    minStay: 1,
    baseRate: 50,
    highPremium: 15,
    minStayExtra: 0,
    extraGuestFee: 0,
    freeGuestLimit: 6,
  },
  villa: {
    label: "villa",
    maxNights: 28,
    minNights: 1,
    maxGuests: 8,
    minStay: 3,
    baseRate: 300,
    highPremium: 120,
    minStayExtra: 500,
    extraGuestFee: 0,
    freeGuestLimit: 8,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES[req.category as string];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyalty = req.loyaltyYears as number;
  const isVip = req.coupon === "VIP";
  const isSeasonHigh = req.season === "high";

  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < cfg.minStay && cfg.minStay > 1) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = cfg.baseRate * nights;
  if (isSeasonHigh) {
    total += cfg.highPremium * nights;
  }
  if (isVip || loyalty >= 3) {
    total -= Math.floor(total / 10);
  }
  if (guests > cfg.freeGuestLimit) {
    total += cfg.extraGuestFee;
  }
  if (cfg.minStayExtra !== 0) {
    total += cfg.minStayExtra;
  }

  const policy = isVip || loyalty > 2 ? "flex" : "strict";
  const line = `${cfg.label}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Ctx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
  shipments: Record<string, Want>;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stock = parseStock(input.stock);
  if (stock === undefined) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
    shipments: {},
  };

  const handlers: Record<string, (ctx: Ctx, event: Record<string, any>) => string | undefined> = {
    order: handleOrder,
    cancel: handleCancel,
    ship: handleShip,
    restock: handleRestock,
    expire: handleExpire,
    return: handleReturn,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, any>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = handlers[event.type];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(ctx, event);
    if (error !== undefined) {
      return { ok: false, error: "event " + index + ": " + error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

function handleOrder(ctx: Ctx, event: Record<string, any>): string | undefined {
  if (!validId(event.id)) {
    return "bad id";
  }
  if (ctx.orders[event.id] !== undefined) {
    return "duplicate order";
  }
  if (!validItem(event.item)) {
    return "bad item";
  }
  if (!validQty(event.qty)) {
    return "bad qty";
  }
  const available = ctx.stock[event.item] ?? 0;
  if (available >= (event.qty as number)) {
    ctx.stock[event.item] = available - (event.qty as number);
    ctx.reserved[event.id] = { item: event.item, qty: event.qty as number };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
    ctx.orders[event.id] = "backordered";
  }
  return undefined;
}

function handleCancel(ctx: Ctx, event: Record<string, any>): string | undefined {
  if (!validId(event.id)) {
    return "bad id";
  }
  if (ctx.reserved[event.id] !== undefined) {
    release(ctx, event.id, "cancelled");
  } else if (ctx.orders[event.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(event.id), 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.rejected++;
  }
  return undefined;
}

function handleShip(ctx: Ctx, event: Record<string, any>): string | undefined {
  if (!validId(event.id)) {
    return "bad id";
  }
  if (event.qty !== undefined && !validQty(event.qty)) {
    return "bad qty";
  }
  const reservation = ctx.reserved[event.id];
  const shipQty = event.qty ?? reservation?.qty;
  if (reservation === undefined || shipQty > reservation.qty) {
    ctx.rejected++;
    return undefined;
  }
  if (shipQty < reservation.qty) {
    reservation.qty = reservation.qty - shipQty;
    ctx.orders[event.id] = "partial";
    return undefined;
  }
  delete ctx.reserved[event.id];
  ctx.orders[event.id] = "shipped";
  ctx.shipments[event.id] = { item: reservation.item, qty: shipQty };
  return undefined;
}

function handleRestock(ctx: Ctx, event: Record<string, any>): string | undefined {
  if (!validItem(event.item)) {
    return "bad item";
  }
  if (!validQty(event.qty)) {
    return "bad qty";
  }
  ctx.stock[event.item] = (ctx.stock[event.item] ?? 0) + (event.qty as number);
  drainQueue(ctx);
  return undefined;
}

function handleExpire(ctx: Ctx, event: Record<string, any>): string | undefined {
  if (!validId(event.id)) {
    return "bad id";
  }
  if (ctx.reserved[event.id] !== undefined) {
    release(ctx, event.id, "expired");
  } else {
    ctx.rejected++;
  }
  return undefined;
}

function handleReturn(ctx: Ctx, event: Record<string, any>): string | undefined {
  if (!validId(event.id)) {
    return "bad id";
  }
  const shipment = ctx.shipments[event.id];
  if (ctx.orders[event.id] !== "shipped" || shipment === undefined) {
    ctx.rejected++;
    return undefined;
  }
  delete ctx.shipments[event.id];
  ctx.stock[shipment.item] = (ctx.stock[shipment.item] ?? 0) + shipment.qty;
  ctx.orders[event.id] = "returned";
  drainQueue(ctx);
  return undefined;
}

function release(ctx: Ctx, id: string, status: string): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = (ctx.stock[holding.item] ?? 0) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  drainQueue(ctx);
}

function drainQueue(ctx: Ctx): void {
  let position = 0;
  while (position < ctx.queue.length) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = ctx.stock[want.item] ?? 0;
    if (onHand < want.qty) {
      position++;
      continue;
    }
    ctx.stock[want.item] = onHand - want.qty;
    ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
    ctx.orders[pendingId] = "reserved";
    delete ctx.pendingWants[pendingId];
    ctx.queue.splice(position, 1);
  }
}

function validId(id: unknown): boolean {
  return typeof id === "string" && id.length > 0;
}

function validItem(item: unknown): boolean {
  return typeof item === "string" && item.length > 0;
}

function validQty(qty: unknown): boolean {
  return Number.isInteger(qty) && (qty as number) >= 1;
}

function parseStock(raw: unknown): Record<string, number> | undefined {
  if (typeof raw !== "object" || raw === null) {
    return undefined;
  }
  const stock: Record<string, number> = {};
  const rawStock = raw as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return undefined;
    }
    stock[item] = rawStock[item] as number;
  }
  return stock;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

interface State {
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  orders: Record<string, string>;
  rejected: number;
  original: Record<string, { item: string; qty: number }>;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function makeState(rawStock: Record<string, unknown>): State | string {
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return "bad stock";
    }
    stock[item] = rawStock[item] as number;
  }
  return {
    stock,
    reserved: {},
    pendingWants: {},
    queue: [],
    orders: {},
    rejected: 0,
    original: {},
  };
}

function onHand(state: State, item: string): number {
  return state.stock[item] === undefined ? 0 : state.stock[item];
}

function serveQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const available = onHand(state, want.item);
    if (available >= want.qty) {
      state.stock[want.item] = available - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function applyOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[event.id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  state.original[event.id] = { item: event.item, qty: event.qty as number };
  const available = onHand(state, event.item);
  if (available >= (event.qty as number)) {
    state.stock[event.item] = available - (event.qty as number);
    state.reserved[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "backordered";
  }
  return null;
}

function applyReturn(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[event.id] !== "shipped") {
    state.rejected = state.rejected + 1;
    return null;
  }
  const dropped = state.original[event.id];
  state.stock[dropped.item] = onHand(state, dropped.item) + dropped.qty;
  state.orders[event.id] = "returned";
  return null;
}

function applyCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    const holding = state.reserved[event.id];
    state.stock[holding.item] = onHand(state, holding.item) + holding.qty;
    delete state.reserved[event.id];
    state.orders[event.id] = "cancelled";
    serveQueue(state);
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function applyShip(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return "event " + index + ": bad qty";
  }
  const held = state.reserved[event.id];
  if (held === undefined) {
    state.rejected = state.rejected + 1;
    return null;
  }
  const shipped = event.qty === undefined ? held.qty : (event.qty as number);
  if (shipped > held.qty) {
    state.rejected = state.rejected + 1;
    return null;
  }
  held.qty = held.qty - shipped;
  state.orders[event.id] = held.qty === 0 ? "shipped" : "partial";
  if (held.qty === 0) {
    delete state.reserved[event.id];
  }
  return null;
}

function applyRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  state.stock[event.item] = onHand(state, event.item) + (event.qty as number);
  serveQueue(state);
  return null;
}

function applyExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    const holding = state.reserved[event.id];
    state.stock[holding.item] = onHand(state, holding.item) + holding.qty;
    delete state.reserved[event.id];
    state.orders[event.id] = "expired";
    serveQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, (s: State, e: Record<string, unknown>, i: number) => string | null> = {
  order: applyOrder,
  cancel: applyCancel,
  ship: applyShip,
  restock: applyRestock,
  expire: applyExpire,
  return: applyReturn,
};

function applyEvent(state: State, event: Record<string, unknown>, index: number): string | null {
  const handler = HANDLERS[event.type as string];
  if (handler === undefined) {
    return "bad type";
  }
  return handler(state, event, index);
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const state = makeState(input.stock as Record<string, unknown>);
  if (typeof state === "string") {
    return { ok: false, error: state };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const error = applyEvent(state, event, index);
    if (typeof error === "string") {
      return { ok: false, error: "event " + index + ": " + error };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const shipped: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  function drainBackorders(): void {
    for (let position = 0; position < queue.length; position++) {
      const pendingId = queue[position];
      const want = pendingWants[pendingId];
      const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
      if (onHand >= want.qty) {
        stock[want.item] = onHand - want.qty;
        reserved[pendingId] = { item: want.item, qty: want.qty };
        orders[pendingId] = "reserved";
        delete pendingWants[pendingId];
        queue.splice(position, 1);
        position = position - 1;
      }
    }
  }

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = stock[event.item] === undefined ? 0 : stock[event.item];
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        drainBackorders();
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        shipped[event.id] = {
          item: reserved[event.id].item,
          qty: (shipped[event.id] === undefined ? 0 : shipped[event.id].qty) + reserved[event.id].qty,
        };
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        shipped[event.id] = {
          item: reserved[event.id].item,
          qty: (shipped[event.id] === undefined ? 0 : shipped[event.id].qty) + (event.qty as number),
        };
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "return") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      const full = shipped[event.id];
      if (full !== undefined && orders[event.id] === "shipped") {
        const back = stock[full.item] === undefined ? 0 : stock[full.item];
        stock[full.item] = back + full.qty;
        delete shipped[event.id];
        orders[event.id] = "returned";
        drainBackorders();
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const held = stock[event.item] === undefined ? 0 : stock[event.item];
      stock[event.item] = held + (event.qty as number);
      drainBackorders();
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        drainBackorders();
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

