export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const originals: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const stockOf = (item: string): number =>
    stock[item] === undefined ? 0 : stock[item];

  const fulfillQueue = (): void => {
    for (let position = 0; position < queue.length; position++) {
      const pendingId = queue[position];
      const want = pendingWants[pendingId];
      const onHand = stockOf(want.item);
      if (onHand >= want.qty) {
        stock[want.item] = onHand - want.qty;
        reserved[pendingId] = { item: want.item, qty: want.qty };
        orders[pendingId] = "reserved";
        delete pendingWants[pendingId];
        queue.splice(position, 1);
        position = position - 1;
      }
    }
  };

  const releaseReservation = (id: string, status: string): void => {
    const holding = reserved[id];
    stock[holding.item] = stockOf(holding.item) + holding.qty;
    delete reserved[id];
    orders[id] = status;
    fulfillQueue();
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      originals[event.id] = { item: event.item, qty: event.qty as number };
      const available = stockOf(event.item);
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        releaseReservation(event.id, "cancelled");
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      stock[event.item] = stockOf(event.item) + (event.qty as number);
      fulfillQueue();
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        releaseReservation(event.id, "expired");
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "return") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      const status = orders[event.id];
      if (status === "shipped" || status === "partial") {
        const orig = originals[event.id];
        stock[orig.item] = stockOf(orig.item) + orig.qty;
        delete reserved[event.id];
        orders[event.id] = "returned";
        fulfillQueue();
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pending: Record<string, Want>;
  shipped: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function stockOf(stock: Record<string, number>, item: string): number {
  const value = stock[item];
  return value === undefined ? 0 : value;
}

function fulfillQueue(state: State): void {
  const { stock, queue, pending, reserved, orders } = state;
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pending[pendingId];
    const onHand = stockOf(stock, want.item);
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pending[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function requireField(
  value: unknown,
  field: string,
  index: number,
): string | string[] {
  if (typeof value !== "string" || value.length === 0) {
    return ["event " + index + ": bad " + field];
  }
  return value;
}

function requireQty(
  value: unknown,
  index: number,
  allowUndefined: boolean,
): number | string[] {
  if (
    (value === undefined && !allowUndefined) ||
    (value !== undefined && (!Number.isInteger(value) || value < 1))
  ) {
    return ["event " + index + ": bad qty"];
  }
  return value === undefined ? -1 : (value as number);
}

function reject(state: State): void {
  state.rejected = state.rejected + 1;
}

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = requireField(event.id, "id", index);
  if (Array.isArray(id)) return id[0];
  const item = requireField(event.item, "item", index);
  if (Array.isArray(item)) return item[0];
  const qty = requireQty(event.qty, index, false);
  if (Array.isArray(qty)) return qty[0];

  if (state.orders[id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (stockOf(state.stock, item) >= qty) {
    state.stock[item] = stockOf(state.stock, item) - qty;
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pending[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = requireField(event.id, "id", index);
  if (Array.isArray(id)) return id[0];

  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = stockOf(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "cancelled";
    fulfillQueue(state);
  } else if (state.orders[id] === "backordered") {
    const position = state.queue.indexOf(id);
    if (position !== -1) state.queue.splice(position, 1);
    delete state.pending[id];
    state.orders[id] = "cancelled";
  } else {
    reject(state);
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = requireField(event.id, "id", index);
  if (Array.isArray(id)) return id[0];
  const shipped = requireQty(event.qty, index, true);
  if (Array.isArray(shipped)) return shipped[0];

  const holding = state.reserved[id];
  if (holding === undefined) {
    reject(state);
  } else if (shipped === -1 || shipped === holding.qty) {
    addShipped(state, id, holding.item, holding.qty);
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if (shipped < holding.qty) {
    addShipped(state, id, holding.item, shipped);
    holding.qty = holding.qty - shipped;
    state.orders[id] = "partial";
  } else {
    reject(state);
  }
  return null;
}

function addShipped(state: State, id: string, item: string, qty: number): void {
  const current = state.shipped[id];
  if (current === undefined) {
    state.shipped[id] = { item, qty };
  } else {
    current.qty = current.qty + qty;
  }
}

function handleReturn(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = requireField(event.id, "id", index);
  if (Array.isArray(id)) return id[0];

  if (state.orders[id] === "shipped" && state.shipped[id] !== undefined) {
    const shipped = state.shipped[id];
    state.stock[shipped.item] = stockOf(state.stock, shipped.item) + shipped.qty;
    delete state.shipped[id];
    state.orders[id] = "returned";
  } else {
    reject(state);
  }
  return null;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  const item = requireField(event.item, "item", index);
  if (Array.isArray(item)) return item[0];
  const qty = requireQty(event.qty, index, false);
  if (Array.isArray(qty)) return qty[0];

  state.stock[item] = stockOf(state.stock, item) + qty;
  fulfillQueue(state);
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = requireField(event.id, "id", index);
  if (Array.isArray(id)) return id[0];

  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = stockOf(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "expired";
    fulfillQueue(state);
  } else {
    reject(state);
  }
  return null;
}

function parseStock(rawStock: Record<string, unknown>): Record<string, number> | null {
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    const value = rawStock[item];
    if (!Number.isInteger(value as number) || (value as number) < 0) {
      return null;
    }
    stock[item] = value as number;
  }
  return stock;
}

const HANDLERS: Record<string, (s: State, e: Record<string, unknown>, i: number) => string | null> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

function applyEvent(state: State, event: unknown, index: number): string | null {
  if (typeof event !== "object" || event === null) {
    return "event " + index + ": malformed";
  }
  const record = event as Record<string, unknown>;
  const handleType = HANDLERS[record.type as string];
  if (handleType === undefined) {
    return "event " + index + ": bad type";
  }
  return handleType(state, record, index);
}

function newState(stock: Record<string, number>): State {
  return {
    stock,
    orders: {},
    reserved: {},
    pending: {},
    shipped: {},
    queue: [],
    rejected: 0,
  };
}

function runEvents(state: State, events: unknown[]): string | null {
  for (let index = 0; index < events.length; index++) {
    const error = applyEvent(state, events[index], index);
    if (error !== null) {
      return error;
    }
  }
  return null;
}

function success(state: State): FulfillmentResult {
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  const stock = parseStock(input.stock as Record<string, unknown>);
  if (stock === null) {
    return { ok: false, error: "bad stock" };
  }

  const state = newState(stock);
  const error = runEvents(state, input.events);
  return error === null ? success(state) : { ok: false, error };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function getStock(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function fillBackorders(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = getStock(stock, want.item);
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(
  id: string,
  status: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): void {
  const holding = reserved[id];
  stock[holding.item] = getStock(stock, holding.item) + holding.qty;
  delete reserved[id];
  orders[id] = status;
  fillBackorders(stock, reserved, pendingWants, queue, orders);
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const status = orders[id];
    if (counts[status] !== undefined) {
      counts[status] = counts[status] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const wantInfo: Record<string, Want> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      wantInfo[event.id] = { item: event.item, qty: event.qty as number };
      const available = getStock(stock, event.item);
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        releaseReservation(event.id, "cancelled", stock, reserved, pendingWants, queue, orders);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      stock[event.item] = getStock(stock, event.item) + (event.qty as number);
      fillBackorders(stock, reserved, pendingWants, queue, orders);
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        releaseReservation(event.id, "expired", stock, reserved, pendingWants, queue, orders);
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "return") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] === "shipped") {
        const want = wantInfo[event.id];
        stock[want.item] = getStock(stock, want.item) + want.qty;
        orders[event.id] = "returned";
        fillBackorders(stock, reserved, pendingWants, queue, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  wants: Record<string, Want>;
  shipped: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function badField(index: number, value: unknown, message: string): string | null {
  return typeof value !== "string" || value.length === 0 ? "event " + index + ": " + message : null;
}

function badQty(index: number, value: unknown): string | null {
  return typeof value !== "number" || !Number.isInteger(value) || value < 1
    ? "event " + index + ": bad qty"
    : null;
}

function removeFromQueue(queue: string[], id: string): void {
  const position = queue.indexOf(id);
  if (position !== -1) {
    queue.splice(position, 1);
  }
}

function fillBackorders(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHandValue = onHand(state.stock, want.item);
    if (onHandValue >= want.qty) {
      state.stock[want.item] = onHandValue - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReserved(state: State, id: string, status: string): void {
  const holding = state.reserved[id];
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  fillBackorders(state);
}

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  const idErr = badField(index, event.id, "bad id");
  if (idErr) {
    return idErr;
  }
  if (state.orders[event.id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const itemErr = badField(index, event.item, "bad item");
  if (itemErr) {
    return itemErr;
  }
  const qtyErr = badQty(index, event.qty);
  if (qtyErr) {
    return qtyErr;
  }
  const available = onHand(state.stock, event.item);
  const want = { item: event.item, qty: event.qty as number };
  state.wants[event.id] = want;
  if (available >= want.qty) {
    state.stock[event.item] = available - want.qty;
    state.reserved[event.id] = want;
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = want;
    state.orders[event.id] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  const idErr = badField(index, event.id, "bad id");
  if (idErr) {
    return idErr;
  }
  if (state.reserved[event.id] !== undefined) {
    releaseReserved(state, event.id, "cancelled");
  } else if (state.orders[event.id] === "backordered") {
    removeFromQueue(state.queue, event.id);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | null {
  const idErr = badField(index, event.id, "bad id");
  if (idErr) {
    return idErr;
  }
  const qtyErr = event.qty === undefined ? null : badQty(index, event.qty);
  if (qtyErr) {
    return qtyErr;
  }
  if (state.reserved[event.id] === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[event.id].qty) {
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
    state.shipped[event.id] = state.wants[event.id];
  } else if ((event.qty as number) < state.reserved[event.id].qty) {
    state.reserved[event.id].qty = state.reserved[event.id].qty - (event.qty as number);
    state.orders[event.id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  const itemErr = badField(index, event.item, "bad item");
  if (itemErr) {
    return itemErr;
  }
  const qtyErr = badQty(index, event.qty);
  if (qtyErr) {
    return qtyErr;
  }
  state.stock[event.item] = onHand(state.stock, event.item) + (event.qty as number);
  fillBackorders(state);
  return null;
}

function handleReturn(state: State, event: Record<string, unknown>, index: number): string | null {
  const idErr = badField(index, event.id, "bad id");
  if (idErr) {
    return idErr;
  }
  if (state.orders[event.id] === "shipped") {
    const want = state.shipped[event.id];
    state.stock[want.item] = onHand(state.stock, want.item) + want.qty;
    delete state.shipped[event.id];
    state.orders[event.id] = "returned";
    fillBackorders(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  const idErr = badField(index, event.id, "bad id");
  if (idErr) {
    return idErr;
  }
  if (state.reserved[event.id] !== undefined) {
    releaseReserved(state, event.id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

type Handler = (state: State, event: Record<string, unknown>, index: number) => string | null;

const HANDLERS: ReadonlyMap<string, Handler> = new Map([
  ["order", handleOrder],
  ["cancel", handleCancel],
  ["ship", handleShip],
  ["restock", handleRestock],
  ["return", handleReturn],
  ["expire", handleExpire],
]);

interface ParsedInput {
  stock: Record<string, number>;
  events: unknown[];
}

type InputResult = { ok: true; value: ParsedInput } | { ok: false; error: string };

function parseStock(raw: unknown): { ok: true; value: Record<string, number> } | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "bad stock" };
  }
  const rawStock = raw as Record<string, unknown>;
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { ok: true, value: stock };
}

function parseInput(raw: unknown): InputResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stock = parseStock(input.stock);
  if (!stock.ok) {
    return stock;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return { ok: true, value: { stock: stock.value, events: input.events } };
}

function runEvents(state: State, events: unknown[]): string | null {
  for (let index = 0; index < events.length; index++) {
    const event = events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return "event " + index + ": malformed";
    }
    const handler = HANDLERS.get(event.type as string);
    if (!handler) {
      return "event " + index + ": bad type";
    }
    const error = handler(state, event, index);
    if (error) {
      return error;
    }
  }
  return null;
}

function buildResult(state: State): FulfillmentResult {
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }
  const state: State = {
    stock: parsed.value.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    wants: {},
    shipped: {},
    queue: [],
    rejected: 0,
  };
  const error = runEvents(state, parsed.value.events);
  if (error) {
    return { ok: false, error };
  }
  return buildResult(state);
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    if (counts[orders[id]] !== undefined) {
      counts[orders[id]] = counts[orders[id]] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

