const FIELD_RULES: ReadonlyArray<{ key: string; check: (value: unknown) => boolean; error: string }> = [
  { key: "channel", check: (v) => typeof v === "string" && v.length > 0, error: "bad channel" },
  { key: "unit", check: (v) => typeof v === "string" && (UNITS as readonly string[]).includes(v), error: "bad unit" },
  { key: "value", check: (v) => Number.isInteger(v), error: "bad value" },
  { key: "at", check: (v) => Number.isInteger(v) && (v as number) >= 0, error: "bad timestamp" },
];

const LEVELS: ReadonlyArray<{ label: string; max: number; alert: boolean }> = [
  { label: "standby", max: 50, alert: false },
  { label: "idle", max: 200, alert: false },
  { label: "active", max: 600, alert: false },
  { label: "loaded", max: 900, alert: true },
  { label: "critical", max: Infinity, alert: true },
];

const NEGATIVE = "negative";
const SEVERITY: Record<string, number> = {
  negative: 5,
  critical: 4,
  loaded: 3,
  active: 2,
  idle: 1,
