  const labels: string[] = [];
  const alerts: string[] = [];

  for (const entry of (raw as { readings: unknown[] }).readings) {
    const index = parsed.length;
    const outcome = parseReading(entry, index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    const millivolts = normalizeValue(outcome.unit, outcome.value);
    parsed.push({ channel: outcome.channel, millivolts, at: outcome.at });
