export function classifySignal(millivolts: number): string {
  if (millivolts >= 0 && millivolts < 50) {
    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
}

function severityRank(label: string): number {
  if (label === "negative") {
    return 5;
  }
  if (label === "critical") {
    return 4;
  }
  if (label === "loaded") {
    return 3;
  }
  if (label === "active") {
    return 2;
  }
  if (label === "idle") {
    return 1;
  }
  return 0;
}

const ALERT_LABELS = new Set(["loaded", "critical", "negative"]);

function collectAlerts(parsed: ParsedReading[]): string[] {
  const alerts: string[] = [];
  for (const reading of parsed) {
    const label = classifySignal(reading.millivolts);
    if (ALERT_LABELS.has(label)) {
      alerts.push(reading.channel + ":" + label);
    }
  }
  return alerts;
}

function collectFlatlines(parsed: ParsedReading[]): string[] {
  const alerts: string[] = [];
  let runStart = 0;
  while (runStart < parsed.length) {
    let runEnd = runStart + 1;
    while (
      runEnd < parsed.length &&
      parsed[runEnd].channel === parsed[runStart].channel &&
      parsed[runEnd].millivolts === parsed[runStart].millivolts
