    if (req.season === "high") {
      total = total + 15 * (req.nights as number);
    }
    if ((req.loyaltyYears as number) >= 3 || req.coupon === "VIP") {
      total = total - Math.floor(total / 10);
    }
    let policy = "strict";
    if (req.coupon === "VIP" || (req.loyaltyYears as number) > 2) {
